renderHTML:
__ht__function(data, gv, cache) {var option = {
    title: {show:false
    },
    backgroundColor: 'transparent',
        color:["#1e98e2","#fb0045","#30c5ed","#9fe7b8","#ff9f7d","#0086e5","#e7bcf2"],
    tooltip: {
        trigger: 'axis',
        axisPointer: {
            type: 'shadow'
        }
    },
    grid: {
        top:0,
        left: '3%',
        right: '4%',
        bottom: '3%',
        containLabel: true
    },
    xAxis: {
        type: 'value',
         axisLabel: {//x轴文字的配置
                show: true,
                textStyle: {
                    color: "#fff",
                }
            },
        boundaryGap: [0, 0.01]
    },
    yAxis: {
        type: 'category',
          axisLabel: {//y轴文字的配置
                textStyle: {
                     color:"#fff",
                     margin: 15
                },
               // formatter: &#39;{value} %&#39;//y轴的每一个刻度值后面加上‘%’号
            },
        data: []
    },
    series: [
        {
            name: 'name1',
            type: 'bar',
             itemStyle: {
                                normal: {
                                    label: {
                                        show: true, 
                                        position: 'right',
                                        textStyle: {
                                            color: '#fff',
                                            fontSize: 12
                                        }
                                    }
                                }
                            },
            data: []
        },
        {
            name: 'name2',
            type: 'bar',
              itemStyle: {
                                normal: {
                                    label: {
                                        show: true, 
                                        position: 'right',
                                        textStyle: {
                                            color: '#fff',
                                            fontSize: 12
                                        }
                                    }
                                }
                            },
            data: []
        }
    ]
};

if (!cache.htmlView) {
    cache.htmlView = document.createElement('div');
    cache.htmlView.style.position = 'absolute';
    cache.htmlChart = echarts.init(cache.htmlView);

    // layoutHTML will be called when the data needs to be drawing
    cache.htmlView.layoutHTML = function () {
        gv.layoutHTML(data, cache.htmlView, false);
        cache.htmlChart.resize();
    };
}

// update data
option.yAxis.data = data.a('yAxis.data');
option.series[0].data = data.a('series0.data');
option.series[1].data=data.a('series1.data');
data.a('chart.text') && (option.title.text = data.a('chart.text'));
data.a('chart.subtext') && (option.title.subtext = data.a('chart.subtext'));
data.a('chart.backgroundColor') && (option.backgroundColor = data.a('chart.backgroundColor'));

cache.htmlChart.setOption(option);

// html for showing
return cache.htmlView;}
